import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Status and evidence","description":"What exists, what is planned, and what each verification result establishes.","frontmatter":{"title":"Status and evidence","description":"What exists, what is planned, and what each verification result establishes."},"headers":[],"relativePath":"status.md","filePath":"status.md","lastUpdated":1794376220000}'),r={name:"status.md"};function s(o,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="status-and-evidence" tabindex="-1">Status and evidence <a class="header-anchor" href="#status-and-evidence" aria-label="Permalink to &quot;Status and evidence&quot;">​</a></h1><p><strong>Review baseline: November 10, 2026.</strong> Software availability and publication are separate claims.</p><h2 id="available-in-this-repository" tabindex="-1">Available in this repository <a class="header-anchor" href="#available-in-this-repository" aria-label="Permalink to &quot;Available in this repository&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Deliverable</th><th>Scope</th></tr></thead><tbody><tr><td>VitePress documentation</td><td>Vision, guides, current design, build roadmap and reference library</td></tr><tr><td>IS373 student support</td><td>Original-assignment-aligned guides, AI prompts, checking worksheet and optional local retrieval lab (not a hosted submission)</td></tr><tr><td>Ordo source audit</td><td>Exact inspected revisions, reuse decisions and known gaps—not donor test results</td></tr><tr><td>Synthetic contract labs</td><td>Seven Rust, ten JavaScript and eight SQLite/Python tests</td></tr><tr><td>Static Svelte welcome scaffold</td><td>A separately tested container-ready landing page; no research backend</td></tr><tr><td>Validation and CI</td><td>Plan traceability, documentation build, links, anchors, assets, sitemap and navigation</td></tr></tbody></table><p>Use actual workflow logs for execution results. Lab counts describe the suites; a passing run does not establish the full application&#39;s behavior. <a href="./engineering/examples">Example scope</a>.</p><h2 id="not-implemented-here" tabindex="-1">Not implemented here <a class="header-anchor" href="#not-implemented-here" aria-label="Permalink to &quot;Not implemented here&quot;">​</a></h2><p>The research Rust workspace, production schema, plugin host, interactive Svelte research interface, canonical resolution service, durable hosted store and model adapters remain planned. Donor code was not bulk imported; donor runtime suites were not executed by this audit. Native hardware quality, retrieval quality and production capacity remain unmeasured.</p><h2 id="public-documentation-mirror-and-project-pages" tabindex="-1">Public documentation mirror and project Pages <a class="header-anchor" href="#public-documentation-mirror-and-project-pages" aria-label="Permalink to &quot;Public documentation mirror and project Pages&quot;">​</a></h2><p>The VitePress documentation is hosted as a <a href="https://kaw393939.github.io/knowledge-lab/" target="_blank" rel="noreferrer">pinned portfolio Pages mirror</a>. The portfolio publication is an independently tested release of the same source, not a second set of docs. It makes the current IS373 student-support pages accessible without requiring a new Pages site. Actual portfolio Pages deployment should be checked against the source revision manifest.</p><p>The standalone <code>is373-rag</code> repository&#39;s Pages settings have not been enabled; its own deployment workflow continues to fail that distinct publication gate. <a href="./project/setup">Mirror and standalone setup</a>.</p><h2 id="publication-is-a-separate-gate" tabindex="-1">Publication is a separate gate <a class="header-anchor" href="#publication-is-a-separate-gate" aria-label="Permalink to &quot;Publication is a separate gate&quot;">​</a></h2><p>The Documentation workflow builds previews on PRs. On main it requires Pages activation, deploys and verifies actual public responses against the source revision. A blocked publication job does not invalidate a successful static build, but it does mean the site is not verified live. <a href="./project/setup">Enable and publish Pages</a>.</p><p>Docker Hub publication, live application deployment, portfolio DNS and account settings require independent evidence. The welcome scaffold does not establish any of them. <a href="./project/hosting">Application hosting</a>.</p><h2 id="which-plan-takes-precedence" tabindex="-1">Which plan takes precedence? <a class="header-anchor" href="#which-plan-takes-precedence" aria-label="Permalink to &quot;Which plan takes precedence?&quot;">​</a></h2><p><a href="./guide/">Start</a> explains intent; <a href="./design/">Design</a> and <a href="./build/">Build</a> lead to the current contracts. The authoritative material remains in <code>project/</code>, <code>reuse/</code> and <code>engineering/</code>. Entry pages summarize and link, not replace it.</p><p>The S0–S7 roadmap supersedes the earlier G-series ordering. Older architecture, reviews and research retain visible reference notices. Reuse the historical Rust kernel, repair its gaps, defer a broker, and separate the hosted API from the private stateful store. Local embedded storage remains an explicit twelve-factor exception.</p><h2 id="next-implementation-gate" tabindex="-1">Next implementation gate <a class="header-anchor" href="#next-implementation-gate" aria-label="Permalink to &quot;Next implementation gate&quot;">​</a></h2><p>Complete S0&#39;s rights, dependency and contract decisions; then extract the bounded S1 job/event behavior. Carry requirement IDs, donor symbols and actual receipts into each issue and PR. Do not close runtime work because a page describes it.</p>',18)])])}const b=t(r,[["render",s]]);export{u as __pageData,b as default};
